// ── Utilities ─────────────────────────────────────────────────────────────────

function hexToRGB(hex) {
    hex = hex.replace("#", "");
    if (hex.length === 3) {
        hex = hex[0]+hex[0] + hex[1]+hex[1] + hex[2]+hex[2];
    }
    return {
        r: parseInt(hex.substring(0, 2), 16),
        g: parseInt(hex.substring(2, 4), 16),
        b: parseInt(hex.substring(4, 6), 16)
    };
}

function makeSolidColor(hexStr) {
    var rgb = hexToRGB(hexStr);
    var sc  = new SolidColor();
    sc.rgb.red   = rgb.r;
    sc.rgb.green = rgb.g;
    sc.rgb.blue  = rgb.b;
    return sc;
}

// ── Layer creators ────────────────────────────────────────────────────────────

function createSolidColorLayer(doc, spec) {
    // spec: { name, color, x, y, width, height }
    var layer = doc.artLayers.add();
    layer.name = spec.name || "Color Layer";

    var sel = [
        [spec.x,              spec.y],
        [spec.x + spec.width, spec.y],
        [spec.x + spec.width, spec.y + spec.height],
        [spec.x,              spec.y + spec.height]
    ];
    doc.selection.select(sel);
    doc.selection.fill(makeSolidColor(spec.color || "#FF0000"));
    doc.selection.deselect();
    return layer;
}

function createTextLayer(doc, spec) {
    // spec: { name, content, color, size, x, y, bold, font }
    var layer = doc.artLayers.add();
    layer.kind  = LayerKind.TEXT;
    layer.name  = spec.name || "Text Layer";

    var ti = layer.textItem;
    ti.contents  = spec.content || "Text";
    ti.size      = new UnitValue(spec.size || 24, "px");
    ti.position  = [new UnitValue(spec.x || 0, "px"), new UnitValue(spec.y || 0, "px")];
    ti.color     = makeSolidColor(spec.color || "#000000");
    if (spec.font)  ti.font = spec.font;
    if (spec.bold)  ti.fauxBold = true;
    if (spec.italic) ti.fauxItalic = true;
    return layer;
}

function createShapeLayer(doc, spec) {
    // spec: { name, color, x, y, width, height, shape: "rect"|"ellipse" }
    // Photoshop shape layers require drawing via path — use solid color as fallback
    return createSolidColorLayer(doc, spec);
}

function createGuides(doc, canvas) {
    // Rule-of-thirds guides
    var w = canvas.width;
    var h = canvas.height;
    doc.guides.add(Direction.VERTICAL,   new UnitValue(Math.round(w / 3), "px"));
    doc.guides.add(Direction.VERTICAL,   new UnitValue(Math.round(w * 2 / 3), "px"));
    doc.guides.add(Direction.HORIZONTAL, new UnitValue(Math.round(h / 3), "px"));
    doc.guides.add(Direction.HORIZONTAL, new UnitValue(Math.round(h * 2 / 3), "px"));
}

// ── Group builder ─────────────────────────────────────────────────────────────

function buildGroup(doc, groupSpec) {
    // groupSpec: { name, layers: [...] }
    var group = doc.layerSets.add();
    group.name = groupSpec.name || "Group";

    var layers = groupSpec.layers || [];
    for (var i = 0; i < layers.length; i++) {
        var ls = layers[i];
        var layer;
        if      (ls.type === "solid_color") layer = createSolidColorLayer(doc, ls);
        else if (ls.type === "text")        layer = createTextLayer(doc, ls);
        else if (ls.type === "shape")       layer = createShapeLayer(doc, ls);
        else continue;

        layer.move(group, ElementPlacement.INSIDE);
    }
    return group;
}

